      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Attendance Details");
      XLSX.writeFile(wb, filename);
      toast.success(`📥 Exported ${dataToExport.length} attendance records to Excel!`);
