  // --- MULTI-LOCATION SLOT HANDLERS ---
  const handleAddLocationSlot = () => {
    const newIdx = eventForm.locations.length;
    setEventForm((prev) => ({
      ...prev,
      locations: [
        ...prev.locations,
        { city: "", venue: "", date: "", time: "09:00 AM — 06:00 PM", address: "", map_url: "" },
      ],
    }));
    setOpenLocationSlots((prev) => [...prev, newIdx]);
  };

